#!/usr/bin/env python3
"""Builds strings.js (ES->EN UI table + data.json EN overlay) from i18n/*.json. ES is the source language (keys)."""
import json, os
H = os.path.dirname(os.path.abspath(__file__))
ui = json.load(open(os.path.join(H, 'i18n/en_ui.json'), encoding='utf-8'))
data = json.load(open(os.path.join(H, 'i18n/en_data.json'), encoding='utf-8'))
out = {'langs': ['es', 'en'], 'ui': {'en': ui}, 'data': {'en': data}}
open(os.path.join(H, 'strings.js'), 'w', encoding='utf-8').write(
  '// Generated by build_strings.py from i18n/en_ui.json + i18n/en_data.json. Do not edit by hand.\nwindow.STRINGS = ' + json.dumps(out, ensure_ascii=False, indent=0) + ';\n')
print('strings.js:', len(ui), 'ui,', len(data), 'data')
